import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CfmV7b-z.js";const m=JSON.parse('{"title":"Sandbox","description":"","frontmatter":{"title":"Sandbox"},"headers":[],"relativePath":"api/lib/sandbox.md","filePath":"api/lib/sandbox.md"}'),d={name:"api/lib/sandbox.md"};function r(i,e,c,l,s,h){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="sandbox" tabindex="-1">Sandbox <a class="header-anchor" href="#sandbox" aria-label="Permalink to &quot;Sandbox&quot;">​</a></h1><h2 id="new-sandbox" tabindex="-1"><code>new Sandbox()</code> <a class="header-anchor" href="#new-sandbox" aria-label="Permalink to &quot;`new Sandbox()` {#new-sandbox}&quot;">​</a></h2><p>A locally sandboxed/isolated environment within a single VM instance</p><h3 id="sandbox-compile" tabindex="-1"><code>Sandbox.compile([name], [template], [compileOpts], [namers], [operations], [director], [store], [log])</code> ⇒ <code>function</code> <a class="header-anchor" href="#sandbox-compile" aria-label="Permalink to &quot;`Sandbox.compile([name], [template], [compileOpts], [namers], [operations], [director], [store], [log])` ⇒ `function` {#sandbox-compile}&quot;">​</a></h3><p>Compiles a locally sandboxed <code>async</code> template rendering function</p><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>[name]</td><td><code>String</code></td><td>The name given to the template (omit to generate via <a href="#sandbox-guid">Sandbox.guid</a>)</td></tr><tr><td>[template]</td><td><code>String</code></td><td>The template content that will be used by the renderer. Omit to load the template from cache.</td></tr><tr><td>[compileOpts]</td><td><code>TemplateOpts</code></td><td>The <a href="./template-options#new-templateopts">TemplateOpts</a></td></tr><tr><td>[namers]</td><td><code>Object</code></td><td>One or more functions responsible for formatting template names into a full path name<br>that is consumable by <code>read</code>/<code>write</code>.<br>Each function accepts the following arguments:<br>1. <em>{Object}</em> <code>namers</code> An object that contains a property for each available naming function.<br>1. <em>{String}</em> <code>partialName</code> The name of the partial that will be converted into a name suitable for a read operation.<br>1. <em>{(TemplateOpts | Function(name:String)😗)}</em> <code>optional</code> Either the <a href="./template-options#new-templateopts">TemplateOpts</a> or a function that takes a single name<br>argument and returns the option value.<br>1. <em>{URLSearchParams}</em> <code>[params]</code> The URLSearchParams that should be used in the converted name.<br>1. <em>{Object}</em> <code>storage</code> The storage object that can contain metadata used by naming operations.<br>1. <em>{Boolean}</em> <code>forContent</code> The flag indicating if the converted name is being used to capture partials.<br>1. <em>{String}</em> <code>extension</code> The file extension override for the converted name (omit to use the default extension set in the options).<br>1. <em>{Boolean}</em> <code>forContext</code> The flag indicating if the converted name is being used to capture context.</td></tr><tr><td>[namers.namer]</td><td><code>function</code></td><td>The default naming function that will be used.</td></tr><tr><td>[namers.namerSuper]</td><td><code>function</code></td><td>The naming function to use when a <code>operations[].read</code> function throws an error. The next<br>reader called in the <code>operations[]</code> list will use the name generated by this reader.</td></tr><tr><td>[operations]</td><td><code>Array.&lt;Object&gt;</code></td><td>One or more functions and/or objects that will handle render-time read/write operations.</td></tr><tr><td>[operations[].read]</td><td><code>function</code></td><td>The reader is an <code>async function</code> responsible for reading partial template content/modules/etc<br>during render-time when a partial template cannot be found within <code>includes</code>. When <code>options.cacheRawTemplates</code> is <em>truthy</em> an<br>attempt will be made to add any missing/read partials into <code>storage.data</code> in order to prevent unnecessary template partial<br>reads for repeated includes. Read functions should not reference any external scope other than the global object space.<br>The following arguments will be passed:<br>1. <em>{String}</em> <code>name</code> The name of the partial that will be read. The read function may be invoked without a <em>name</em> parameter when<br>the intent is to capture all partials in a single read opteration that will be included.<br>1. <em>{String}</em> <code>path</code> The path to the partial that will be read. The read function may be invoked without a <em>path</em> parameter when<br>the intent is to capture all partials in a single read opteration that will be included.<br>1. <em>{String}</em> <code>ext</code> The path file extension to the partial that will be read. The read function may be invoked without an <em>ext</em><br>parameter when the intent is to capture all partials in a single read opteration that will be included.<br>1. <em>{Boolean}</em> <code>forContent</code> The flag indicating that the read is for content. Otherwise, the read is for rendering functions.<br>1. <em>{(TemplateOpts | Function(name:String)😗)}</em> <code>optional</code> Either the <a href="./template-options#new-templateopts">TemplateOpts</a> or a function that takes a single name<br>argument and returns the option value.<br>1. <em>{URLSearchParams}</em> <code>[params]</code> The URLSearchParams that should be used during the read<br>1. <em>{Object}</em> <code>storage</code> The storage object that can contain metadata for read operations and should contain a <strong>data</strong> object<br>that stores each of the read paratial template content/metadata.<br>1. <em>{Function}</em> <code>[formatter]</code> The function that will format reads/writes during include discovery (if any). The formatting function<br>takes 1 or 2 arguments with the first being the content that will be formatted and the second being <code>options.readFormatOptions</code> for<br>reads and <code>options.writeFormatOptions</code> for writes.<br>The returned result should be a valid string.<br>1. <em>{Boolean}</em> <code>[close]</code> A flag indicating whether or not any resources used during the read should be closed/cleaned up after the<br>read completes. Closure may be dependent upon the policy set on the options.<br>1. <em>{Object}</em> <code>[log]</code> A logger that can contain functions for each of the following: <code>error</code>/<code>warn</code>/<code>info</code>/<code>debug</code>.<br>Read functions can return the partial template content and/or it can be set on the <code>storage.data</code>.<br>Returning <code>true</code> will stop any further rendering from processing resulting in the rendering function returning a <em>blank</em> string.</td></tr><tr><td>[operations[].write]</td><td><code>function</code></td><td>The write function that will be used for writting newly discovered template sources.<br>Accepts the same arguments as <code>operations[].read</code> and all <em>scoped</em> functions will be available. Can return a <strong>rendering</strong><br>function that will prevent further iteration of any subsequent <code>operations[].write</code> invocations.</td></tr><tr><td>[operations[].finish]</td><td><code>function</code></td><td>An <code>async function</code> that can perform cleanup tasks for a reader. Arguments passed are<br><code>storage</code>, <code>optional</code> and <code>log</code> as described for <code>operations[].read</code>.<br><strong>after rendering has completed</strong>. Arguments passed are <code>storage</code>, <code>optional</code> and <code>log</code> as described for <code>operations[].read</code>. All<br>functions defined within <code>operations[].scopes</code> will be available by name.</td></tr><tr><td>[operations[].scopes]</td><td><code>Array.&lt;function()&gt;</code></td><td>Zero or more functions that will be in scope when the read function is called.<br>Scoped functions can assit with complex read/write that can benefit from separate supporting functions. For example, <code>[myFunc(){}]</code><br>could be referenced like <code>async function myReader(){ myFunc(); ... }</code>.</td></tr><tr><td>[director]</td><td><code>Director</code></td><td>The <a href="./director#director">Director</a> that will be for extracting <a href="./director#director-directives">Director.directives</a></td></tr><tr><td>[store]</td><td><code>Object</code></td><td>The private storage set during compilation that will be passed during naming/reads. Contents should only<br>contain <strong>valid JSON</strong> properties that can be serialized/deserialized.</td></tr><tr><td>[store.data]</td><td><code>Object</code></td><td>The cached partials that can be included in the template with the name of the template as a<br>property of the object</td></tr><tr><td>[store.data[].name]</td><td><code>String</code></td><td>The name of the partial template</td></tr><tr><td>[store.data[].content]</td><td><code>String</code></td><td>The partial template content</td></tr><tr><td>[store.data[].params]</td><td><code>Object</code></td><td>The parameters that will be added to scope when the template is parsed</td></tr><tr><td>[log]</td><td><code>Object</code></td><td>The log flags that will determine what output will be sent to the <code>console</code> (if any) during rendering</td></tr><tr><td>[log.debug]</td><td><code>Boolean</code></td><td><code>true</code> to output <code>console.debug</code> level log</td></tr><tr><td>[log.info]</td><td><code>Boolean</code></td><td><code>true</code> to output <code>console.info</code> level log</td></tr><tr><td>[log.warn]</td><td><code>Boolean</code></td><td><code>true</code> to output <code>console.warn</code> level log</td></tr><tr><td>[log.error]</td><td><code>Boolean</code></td><td><code>true</code> to output <code>console.error</code> level log</td></tr></tbody></table><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> — The rendering <code>async function</code> that returns a template result string based upon the provided context. The following arguments apply:</li></ul><ol><li><em>{Object}</em> <code>context</code> The context JSON that can be used as data during rendering</li><li><em>{TemplateOpts}</em> <code>[renderOptions]</code> The rendering options that will superceed any <strong>compile-time</strong> options</li><li><em>{Function}</em> <code>[readFormatter]</code> The function that will format read partials during include discovery (if any). The formatting function takes 1 or 2 arguments with the first being the content that will be formatted and the second being the <code>options.readFormatOptions</code>. The returned result should be a valid string.</li><li><em>{Function}</em> <code>[writeFormatter]</code> The function that will format written sources during include discovery (if any). The formatting function takes 1 or 2 arguments with the first being the content that will be formatted and the second being the <code>options.writeFormatOptions</code>. The returned result should be a valid string.</li><li><em>{Object}</em> <code>[sharedStore]</code> An object used for <em>in-memory</em> storage space that can be shared between rendering functions. This ensures that updated data within a renderer execution will be retained between rendering calls from the same renderer or different renderers that are passed the same <em>shared store</em>.</li></ol><h3 id="sandbox-deserialzefunction" tabindex="-1"><code>Sandbox.deserialzeFunction(functionString)</code> ⇒ <code>function</code> | <code>null</code> <a class="header-anchor" href="#sandbox-deserialzefunction" aria-label="Permalink to &quot;`Sandbox.deserialzeFunction(functionString)` ⇒ `function` \\| `null` {#sandbox-deserialzefunction}&quot;">​</a></h3><p>Deserialzes a function string within a locally sandboxed environment (only global variables are accessible)</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>functionString</td><td><code>String</code></td><td>The function string to deserialize</td></tr></tbody></table><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> | <code>null</code> — The deserialized function</li></ul><h3 id="sandbox-deserialzeblock" tabindex="-1"><code>Sandbox.deserialzeBlock(block, [name], [isAsync])</code> ⇒ <code>function</code> | <code>undefined</code> <a class="header-anchor" href="#sandbox-deserialzeblock" aria-label="Permalink to &quot;`Sandbox.deserialzeBlock(block, [name], [isAsync])` ⇒ `function` \\| `undefined` {#sandbox-deserialzeblock}&quot;">​</a></h3><p>Deserialzes a code block iwthin a locally sandboxed environment (only global variables are accessible)</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>block</td><td><code>String</code> | <code>function</code></td><td>The code block to deserialize</td></tr><tr><td>[name]</td><td><code>String</code></td><td>A name that will be given to the function</td></tr><tr><td>[isAsync]</td><td><code>Boolean</code></td><td><code>true</code> when the function is <code>async</code></td></tr></tbody></table><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>function</code> | <code>undefined</code> — The deserialized function</li></ul><h3 id="sandbox-serialzefunction" tabindex="-1"><code>Sandbox.serialzeFunction(func)</code> ⇒ <code>String</code> | <code>null</code> <a class="header-anchor" href="#sandbox-serialzefunction" aria-label="Permalink to &quot;`Sandbox.serialzeFunction(func)` ⇒ `String` \\| `null` {#sandbox-serialzefunction}&quot;">​</a></h3><p>Serialzes a function</p><h4 id="parameters-3" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-3" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td>func</td><td><code>function</code></td><td>The function to serialize</td></tr></tbody></table><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>String</code> | <code>null</code> — The serialized function</li></ul><h3 id="sandbox-guid" tabindex="-1"><code>Sandbox.guid([value], [hyphenate=true])</code> ⇒ <code>String</code> <a class="header-anchor" href="#sandbox-guid" aria-label="Permalink to &quot;`Sandbox.guid([value], [hyphenate=true])` ⇒ `String` {#sandbox-guid}&quot;">​</a></h3><p>Generates a GUID or formats an existing <code>value</code></p><h4 id="parameters-4" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-4" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>[value]</td><td><code>String</code></td><td></td><td>when present, will format the value by add any missing hyphens (if <code>hyphenate=true</code>)<br>instead of generating a new value</td></tr><tr><td>[hyphenate=true]</td><td><code>Boolean</code></td><td>true</td><td>true to include hyphens in generated result</td></tr></tbody></table><h4 id="returns-4" tabindex="-1">Returns <a class="header-anchor" href="#returns-4" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>String</code> — the generated GUID</li></ul><h3 id="sandbox-global" tabindex="-1"><code>Sandbox.global</code> ⇒ <code>Object</code> <a class="header-anchor" href="#sandbox-global" aria-label="Permalink to &quot;`Sandbox.global` ⇒ `Object` {#sandbox-global}&quot;">​</a></h3><h4 id="returns-5" tabindex="-1">Returns <a class="header-anchor" href="#returns-5" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><ul><li><code>Object</code> — The global object. Typically, <code>window</code> when ran within a browser or <code>global</code> when ran on a server</li></ul>',37)])])}const b=t(d,[["render",r]]);export{m as __pageData,b as default};
